/**
 * Regenerates src/viral/daily-templates.ts from content/daily-state.json.
 *
 * This file is GENERATED, not hand-edited -- same philosophy as
 * scripts/hooks-doc.mjs regenerating content/hook-library.md. The state file
 * is the source of truth (full props per video); this just serializes it.
 * Safe to run repeatedly: it fully overwrites daily-templates.ts each time.
 *
 * V01-V06 live in src/viral/templates.ts (locked, hand-authored, the A/B
 * baseline) and are NEVER written here -- only state entries with
 * source !== "seed-existing" and status !== "failed" get a composition.
 */
import { writeFileSync } from "node:fs";

const pascalCase = (s) =>
  s
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean)
    .map((w) => w[0].toUpperCase() + w.slice(1).toLowerCase())
    .join("");

const CATEGORY_LABEL = {
  identity: "Identity",
  "knowledge-gap": "KnowledgeGap",
  "comment-bait": "CommentBait",
  educational: "Educational",
  story: "Story",
};

/** Composition id, e.g. "Viral-07-CommentBait-DropYourBirthDate". */
export const compositionId = (v) =>
  `Viral-${v.v.replace("V", "")}-${CATEGORY_LABEL[v.category] ?? pascalCase(v.category)}-${pascalCase(v.title).slice(0, 40)}`;

const litStr = (s) => JSON.stringify(s);
const litArr = (arr) => `[${arr.map(litStr).join(", ")}]`;

const propsLiteral = (v) => {
  const p = v.props;
  return [
    "{",
    `    hookText: ${litStr(p.hookText)},`,
    p.hookAccent !== undefined ? `    hookAccent: ${litStr(p.hookAccent)},` : null,
    p.hookSub !== undefined ? `    hookSub: ${litStr(p.hookSub)},` : null,
    `    variant: ${litStr(p.variant)},`,
    `    buildSetup: ${litStr(p.buildSetup)},`,
    `    buildReveal: ${litStr(p.buildReveal)},`,
    `    number: ${p.number},`,
    `    numberLabel: ${litStr(p.numberLabel)},`,
    `    traits: ${litArr(p.traits)},`,
    `    ctaText: ${litStr(p.ctaText)},`,
    `    music: MUSIC.${p.music},`,
    // Per-video act structure. Its absence is what made every composition
    // durationInFrames={ACT.total} and every render exactly 17.450667s.
    p.structure
      ? `    structure: { hook: ${p.structure.hook}, build: ${p.structure.build}, value: ${p.structure.value}, cta: ${p.structure.cta} },`
      : null,
    "  }",
  ]
    .filter(Boolean)
    .join("\n");
};

const coverLiteral = (v) => {
  const p = v.props;
  return [
    "{",
    `    kicker: ${litStr(v.cover?.kicker ?? v.numberLabelShort ?? p.numberLabel)},`,
    `    title: ${litStr(v.cover?.title ?? p.hookText)},`,
    `    accent: ${litStr(v.cover?.accent ?? (p.hookAccent ?? ""))},`,
    `    number: ${p.number},`,
    "  }",
  ].join("\n");
};

export const buildDailyTemplatesSource = (state) => {
  const videos = state.videos.filter(
    (v) => v.source !== "seed-existing" && v.status !== "failed",
  );

  const templateEntries = videos
    .map((v) => `  ${litStr(compositionId(v))}: ${propsLiteral(v)},`)
    .join("\n\n");

  const coverEntries = videos
    .map((v) => `  ${litStr(compositionId(v))}: ${coverLiteral(v)},`)
    .join("\n\n");

  // MUSIC is only referenced by a props literal, so emitting the import with
  // zero videos leaves it unused and `tsc` fails on TS6133 -- which happens on
  // a fresh clone before the first run, and on any day where every render
  // failed. The file must typecheck when it is empty.
  const musicImport = videos.length ? `import { MUSIC } from "../lib/brand";\n` : "";

  return `/**
 * GENERATED FILE -- do not hand-edit.
 *
 * Regenerated by scripts/lib/templates-gen.mjs (called from
 * scripts/daily-viral.mjs) from content/daily-state.json every run. V01-V06
 * are the locked baseline and live in src/viral/templates.ts instead -- this
 * file only ever holds V07 onward.
 *
 * Registered into the Root once, in src/Root.tsx, by merging these objects
 * into the same Folder loops that render VIRAL_TEMPLATES / VIRAL_COVERS.
 */
${musicImport}import type { ViralVideoProps } from "./ViralVideo";

export const DAILY_TEMPLATES: Record<string, ViralVideoProps> = {
${templateEntries}
};

export const DAILY_COVERS: Record<
  string,
  { kicker: string; title: string; accent: string; number: number }
> = {
${coverEntries}
};
`;
};

export const writeDailyTemplates = (state, path = "src/viral/daily-templates.ts") => {
  writeFileSync(path, buildDailyTemplatesSource(state));
};
